import unittest

import more_itertools as mi


class IchunkedNonpositiveTests(unittest.TestCase):
    def test_zero_returns_no_chunks(self):
        for values in ([], [1], [1, 2, 3]):
            with self.subTest(values=values):
                self.assertEqual(
                    [list(c) for c in mi.ichunked(values, 0)], []
                )

    def test_zero_does_not_consume_input(self):
        values = iter([1, 2, 3])
        list(mi.ichunked(values, 0))
        self.assertEqual(list(values), [1, 2, 3])

    def test_negative_raises_even_for_empty_input(self):
        for values in ([], [1], [1, 2, 3]):
            for n in (-1, -2, -100):
                with self.subTest(values=values, n=n):
                    with self.assertRaisesRegex(
                        ValueError, '^n must be at least 0$'
                    ):
                        list(mi.ichunked(values, n))

    def test_negative_does_not_consume_input(self):
        values = iter([1, 2, 3])
        with self.assertRaises(ValueError):
            list(mi.ichunked(values, -1))
        self.assertEqual(list(values), [1, 2, 3])

    def test_positive_boundary_and_partial_chunk(self):
        for n, expected in ((1, [[1], [2], [3]]), (2, [[1, 2], [3]])):
            with self.subTest(n=n):
                self.assertEqual(
                    [list(c) for c in mi.ichunked([1, 2, 3], n)], expected
                )

import unittest

import more_itertools as mi


class FalsyError(Exception):
    def __bool__(self):
        return False


class BrokenRepr:
    def __repr__(self):
        raise AssertionError('repr must not be called')


class CustomExceptionTests(unittest.TestCase):
    def test_falsy_too_long(self):
        for function in (mi.one, mi.only):
            with self.subTest(function=function.__name__):
                exc = FalsyError('custom overflow')
                with self.assertRaises(FalsyError) as caught:
                    function(iter([1, 2]), too_long=exc)
                self.assertIs(caught.exception, exc)

    def test_falsy_too_short(self):
        exc = FalsyError('custom underflow')
        with self.assertRaises(FalsyError) as caught:
            mi.one(iter([]), too_short=exc)
        self.assertIs(caught.exception, exc)

    def test_custom_exception_skips_repr(self):
        for function in (mi.one, mi.only):
            for error_type in (FalsyError, RuntimeError):
                for items in ([BrokenRepr(), 2], [1, BrokenRepr()]):
                    with self.subTest(function=function.__name__, error=error_type.__name__):
                        exc = error_type('requested')
                        with self.assertRaises(error_type) as caught:
                            function(iter(items), too_long=exc)
                        self.assertIs(caught.exception, exc)

    def test_custom_exception_class_skips_repr(self):
        for function in (mi.one, mi.only):
            with self.subTest(function=function.__name__):
                with self.assertRaises(RuntimeError):
                    function([BrokenRepr(), BrokenRepr()], too_long=RuntimeError)

    def test_none_uses_default_errors(self):
        for function in (mi.one, mi.only):
            with self.subTest(function=function.__name__):
                with self.assertRaises(ValueError) as caught:
                    function([1, 2], too_long=None)
                self.assertEqual(str(caught.exception), 'Expected exactly one item in iterable, but got 1, 2, and perhaps more.')
        with self.assertRaises(ValueError) as caught:
            mi.one([], too_short=None)
        self.assertEqual(str(caught.exception), 'too few items in iterable (expected 1)')

    def test_non_error_boundaries(self):
        exc = FalsyError('unused')
        item = BrokenRepr()
        for function in (mi.one, mi.only):
            with self.subTest(function=function.__name__):
                self.assertIs(function([item], too_long=exc), item)
        self.assertEqual(mi.only([], default='missing', too_long=exc), 'missing')


