import sys
import unittest

import tomli


class TestKeyPartsLimit(unittest.TestCase):
    def documents(self, key):
        return (
            ("assignment", key + " = 42", (), 42),
            ("table", "[" + key + "]\nvalue = 42", (), {"value": 42}),
            ("array table", "[[" + key + "]]\nvalue = 42", (), [{"value": 42}]),
            ("inline table", "root = {" + key + " = 42}", ("root",), 42),
        )

    def test_key_parts_at_limit(self):
        count = sys.getrecursionlimit()
        key = ".".join(["part"] * count)
        for context, document, prefix, expected in self.documents(key):
            with self.subTest(context=context):
                result = tomli.loads(document)
                for part in prefix + ("part",) * count:
                    result = result[part]
                self.assertEqual(result, expected)

    def test_key_parts_over_limit(self):
        key = ".".join(["part"] * (sys.getrecursionlimit() + 1))
        for context, document, _, _ in self.documents(key):
            with self.subTest(context=context):
                with self.assertRaises(RecursionError):
                    tomli.loads(document)

    def test_quoted_dots_are_not_parts(self):
        key = ".".join(["part"] * (sys.getrecursionlimit() + 1))
        self.assertEqual(tomli.loads('"' + key + '" = 42'), {key: 42})

    def test_mixed_quoted_parts_over_limit(self):
        parts = ["bare", "'literal.dot'", '"basic.dot"', "''"]
        key = " . ".join(
            parts[i % len(parts)] for i in range(sys.getrecursionlimit() + 1)
        )
        with self.assertRaises(RecursionError):
            tomli.loads(key + " = 42")

import unittest

import tomli


class TestInlineTables11(unittest.TestCase):
    def test_newlines_without_trailing_comma(self):
        self.assertEqual(
            tomli.loads("t = {\n a = 1\n ,\n b = 2\n}\nafter = true"),
            {"t": {"a": 1, "b": 2}, "after": True},
        )

    def test_single_line_trailing_comma(self):
        self.assertEqual(tomli.loads("t = {a = 1,}"), {"t": {"a": 1}})

    def test_empty_multiline_table(self):
        self.assertEqual(tomli.loads("t = {\n\t\n}"), {"t": {}})

    def test_nested_tables_and_crlf(self):
        self.assertEqual(
            tomli.loads("t = [{\r\n a.b = {\r\n c = 1,\r\n},\r\n}, {}]"),
            {"t": [{"a": {"b": {"c": 1}}}, {}]},
        )

    def test_comments_between_entries(self):
        self.assertEqual(
            tomli.loads(
                "t = {# opening\n a = 1 # value\n , # separator\n"
                " b = 2, # trailing\n # closing\n}"
            ),
            {"t": {"a": 1, "b": 2}},
        )

    def test_invalid_separators_and_unclosed_tables(self):
        for doc in (
            "t = {,}",
            "t = {a = 1,,}",
            "t = {a = 1\n b = 2}",
            "t = {a = 1,\n",
            "t = {\n",
        ):
            with self.subTest(doc=doc):
                with self.assertRaises(tomli.TOMLDecodeError):
                    tomli.loads(doc)

    def test_duplicate_and_frozen_keys(self):
        for doc in (
            "t = {\n a = 1,\n a = 2,\n}",
            "t = {\n a = {b = 1,},\n a.c = 2,\n}",
        ):
            with self.subTest(doc=doc):
                with self.assertRaises(tomli.TOMLDecodeError):
                    tomli.loads(doc)

import pytest

from packaging.licenses import canonicalize_license_expression


@pytest.mark.parametrize(
    ("expression", "expected"),
    [
        ("LicenseRef-Foo OR LicenseRef-foo", "LicenseRef-Foo OR LicenseRef-Foo"),
        ("LicenseRef-foo AND LicenseRef-FOO", "LicenseRef-foo AND LicenseRef-foo"),
        (
            "(lIcEnSeReF-MiXeD.1-2 or LICENSEREF-mixed.1-2) and LicenseRef-MIXED.1-2",
            "(LicenseRef-MiXeD.1-2 OR LicenseRef-MiXeD.1-2) AND LicenseRef-MiXeD.1-2",
        ),
        (
            "LicenseRef-A OR LicenseRef-B OR LicenseRef-a OR LicenseRef-b",
            "LicenseRef-A OR LicenseRef-B OR LicenseRef-A OR LicenseRef-B",
        ),
        (
            "LicenseRef-Foo with classpath-exception-2.0 OR LicenseRef-foo or mit",
            "LicenseRef-Foo WITH Classpath-exception-2.0 OR LicenseRef-Foo OR MIT",
        ),
    ],
)
def test_licenseref_case_variants_use_first_spelling(
    expression: str, expected: str
) -> None:
    assert canonicalize_license_expression(expression) == expected


def test_licenseref_first_spelling_is_local_to_expression() -> None:
    assert canonicalize_license_expression("LicenseRef-Foo") == "LicenseRef-Foo"
    assert (
        canonicalize_license_expression("LicenseRef-foo OR LicenseRef-FOO")
        == "LicenseRef-foo OR LicenseRef-foo"
    )

import pytest

from packaging import dependency_groups
from packaging.errors import ExceptionGroup
from packaging.requirements import InvalidRequirement


@pytest.mark.parametrize("first", [["not a requirement!!!"], [{}], "invalid list"])
def test_sibling_includes_after_parse_error(first):
    resolver = dependency_groups.DependencyGroupResolver(
        {
            "root": [{"include-group": "first"}, {"include-group": "sibling"}],
            "first": first,
            "sibling": [{"include-group": "nested"}],
            "nested": [{"include-group": "missing"}],
        }
    )
    with pytest.raises(ExceptionGroup) as caught:
        resolver.resolve("root")
    expected_first = (
        TypeError if isinstance(first, str)
        else InvalidRequirement if isinstance(first[0], str)
        else dependency_groups.InvalidDependencyGroupObject
    )
    assert [type(error) for error in caught.value.exceptions] == [
        expected_first, LookupError
    ]
    assert "'missing' not found" in str(caught.value.exceptions[1])


@pytest.mark.parametrize("shared", [[{}, "invalid requirement!!!"], None])
def test_diamond_failure_reported_once_per_resolve(shared):
    groups = {
        "root": [{"include-group": "left"}, {"include-group": "right"}],
        "left": [{"include-group": "Shared_Group"}],
        "right": [{"include-group": "shared-group"}, {"include-group": "other"}],
        "other": [{"include-group": "missing-other"}],
    }
    if shared is not None:
        groups["shared_group"] = shared
    resolver = dependency_groups.DependencyGroupResolver(groups)
    for _ in range(2):
        with pytest.raises(ExceptionGroup) as caught:
            resolver.resolve("root")
        expected = (
            [dependency_groups.InvalidDependencyGroupObject, InvalidRequirement]
            if shared is not None else [LookupError]
        )
        assert [type(error) for error in caught.value.exceptions] == expected + [LookupError]
        assert "'missing-other' not found" in str(caught.value.exceptions[-1])


def test_successful_diamond_preserves_duplicate_requirements():
    resolver = dependency_groups.DependencyGroupResolver(
        {
            "root": [{"include-group": "left"}, {"include-group": "right"}],
            "left": [{"include-group": "shared"}],
            "right": [{"include-group": "shared"}],
            "shared": ["attrs>=22"],
        }
    )
    assert tuple(map(str, resolver.resolve("root"))) == ("attrs>=22", "attrs>=22")

import ast
from unittest.mock import patch

import pytest


@pytest.mark.parametrize("quote", ["'", '"'])
@pytest.mark.parametrize("value", ["linux", "", "  \t  ", "한글", "3.14", "a'b", 'a"b'])
def test_plain_marker_strings_skip_literal_eval(quote, value):
    from packaging._parser import parse_marker

    if quote in value:
        pytest.skip("The tokenizer does not allow the delimiter inside the value")
    with patch.object(ast, "literal_eval", side_effect=AssertionError("slow path")):
        parsed = parse_marker(f"os_name == {quote}{value}{quote}")
    assert parsed[0][2].value == value


@pytest.mark.parametrize(
    ("token", "expected"),
    [(r'"a\tb"', "a\tb"), (r"'\x41'", "A"), (r'"a\\b"', "a\\b"), (r'"\u03b1"', "α")],
)
def test_escaped_marker_strings_keep_decoding(token, expected):
    from packaging._parser import parse_marker

    assert parse_marker(f"os_name == {token}")[0][2].value == expected


@pytest.mark.parametrize("value", ["a\nb", "a\rb", "a\r\nb", "a\0b", "C:\\", r"\x"])
def test_invalid_marker_strings_keep_rejection(value):
    from packaging.markers import InvalidMarker, Marker

    with pytest.raises(InvalidMarker, match="Invalid quoted string"):
        Marker(f'os_name == "{value}"')


def test_requirement_markers_skip_literal_eval():
    from packaging.requirements import Requirement

    with patch.object(ast, "literal_eval", side_effect=AssertionError("slow path")):
        requirement = Requirement('demo; python_version >= "3.10" and os_name == "posix"')
    assert requirement.marker.evaluate({"python_version": "3.11", "os_name": "posix"})

import pytest

from packaging.pylock import Pylock, PylockSelectError


@pytest.mark.parametrize("field", ["extras", "dependency_groups"])
@pytest.mark.parametrize("declared", [None, [], ["known"]])
@pytest.mark.parametrize("selected", [["missing"], ["known", "missing"]])
def test_unknown_selection_fails(field, declared, selected):
    data = {"lock-version": "1.0", "created-by": "test", "packages": []}
    if declared is not None:
        data[field.replace("_", "-")] = declared
    lock = Pylock.from_dict(data)
    with pytest.raises(PylockSelectError):
        list(lock.select(tags=[], **{field: selected}))


@pytest.mark.parametrize(
    "selected, expected",
    [(None, ["base", "dev"]), ([], ["base"]),
     (["dev"], ["base", "dev"]), (["docs"], ["base", "docs"]),
     (["dev", "docs", "dev"], ["base", "dev", "docs"])],
)
def test_default_groups_are_selectable(selected, expected):
    lock = Pylock.from_dict({
        "lock-version": "1.0", "created-by": "test",
        "dependency-groups": ["docs"], "default-groups": ["dev"],
        "packages": [
            {"name": name, "directory": {"path": "."}, **marker}
            for name, marker in [
                ("base", {}),
                ("dev", {"marker": "'dev' in dependency_groups"}),
                ("docs", {"marker": "'docs' in dependency_groups"}),
            ]
        ],
    })
    assert [p.name for p, _ in lock.select(
        tags=[], dependency_groups=selected
    )] == expected


@pytest.mark.parametrize("declared", [None, []])
@pytest.mark.parametrize("selected", [None, []])
def test_empty_selection_is_valid(declared, selected):
    data = {"lock-version": "1.0", "created-by": "test", "packages": []}
    if declared is not None:
        data.update({"extras": declared, "dependency-groups": declared})
    lock = Pylock.from_dict(data)
    assert list(lock.select(tags=[], extras=selected, dependency_groups=selected)) == []


def test_known_extra_selects_package():
    lock = Pylock.from_dict({
        "lock-version": "1.0", "created-by": "test", "extras": ["feature"],
        "packages": [{"name": "feature", "directory": {"path": "."},
                      "marker": "'feature' in extras"}],
    })
    assert [p.name for p, _ in lock.select(
        tags=[], extras=["feature", "feature"]
    )] == ["feature"]

import pytest

import click


@pytest.mark.parametrize(
    ("limit", "expected"), [(0, ""), (1, "."), (2, ".."), (3, "...")]
)
def test_short_help_tiny_limit(limit, expected):
    command = click.Command("example", help="A lengthy description")
    assert command.get_short_help_str(limit) == expected


@pytest.mark.parametrize(
    ("help_text", "limit", "expected"),
    [
        ("123 567 90123.", 10, "123 567..."),
        ("123 5678 xxxxxx", 10, "123..."),
        ("123 567 90", 10, "123 567 90"),
        ("A. More words", 2, "A."),
        ("A", 1, "A"),
        ("", 0, ""),
        ("\n\b\nA lengthy description", 2, ".."),
    ],
)
def test_short_help_abbreviation_boundaries(help_text, limit, expected):
    command = click.Command("example", help=help_text)
    assert command.get_short_help_str(limit) == expected
